import childProcess from "node:child_process"
const cli = process.env.npm_execpath?.endsWith("npm-cli.js") ? [process.execPath, process.env.npm_execpath] : ["npm"]
export function install(name, directory) {
  return childProcess.spawnSync(cli[0], [...cli.slice(1), "install", "--ignore-scripts", "--no-save", "--prefix", directory, name], { stdio: "inherit" })
}
